                this->extremeTrailStartDatesInMonths[mission] = this->extremeTrailYearReached;
                this->extremeTrailYearReached += this->extremeTrailMonthsTakenOrChicken[mission];
            }
            if (mission != 20) {
                this->extremeTrailStartDatesInMonths[mission] = this->extremeTrailYearReached;
            }
        }
    }

}
}

