                DAT_BuildingsState::ptr)(buildingID, playerID, 50);
            MACRO_CALL_MEMBER(Map::Buildings::BuildingsState_Func::destroyBuilding, DAT_BuildingsState::ptr)(
                buildingID);
            return TRUE;
        }
        return FALSE;
    }
}
}

