    void AICState::generateSiegeCreationInformation(int playerID, int buildingID, int unitID)
    {
        if (DAT_GameState::instance.playerDataArray[playerID].aiType == OpenSHC::AI::AIT_NULL)
            return;
        int i = 0;
        if (DAT_GameSynchronyState::instance.currentGameMode == OpenSHC::Game::GM_SOLITARY)
            return;

        int siegeIndex;
        if (DAT_UnitsState::instance.units[unitID].unitType == OpenSHC::Map::Units::UT_S_TREBUCHET)
            siegeIndex = 2;
        else if (DAT_UnitsState::instance.units[unitID].unitType == OpenSHC::Map::Units::UT_S_FBALLISTA)
            siegeIndex = 3;
        else
            return;

        int const slot = DAT_SkirmishDefinedData::instance.SiegeEngineMetaInfoArray[siegeIndex].slot;
        int const locationCount
            = DAT_GameState::instance.playerDataArray[playerID].aivUnitLocationSlotLocationCount[slot];
        while (i < locationCount) {
            int const index = i;
            i++;
            if (DAT_GameState::instance.playerDataArray[playerID].aivUnitLocationSlots[slot][index] > 0
                && buildingID
                    == DAT_GameState::instance.playerDataArray[playerID]
                        .aiSiegeCreationInformation[siegeIndex][index]
                        .buildingID) {
                DAT_GameState::instance.playerDataArray[playerID].aiSiegeCreationInformation[siegeIndex][index].unitID
                    = unitID;
                DAT_GameState::instance.playerDataArray[playerID].aiSiegeCreationInformation[siegeIndex][index].uid
                    = DAT_UnitsState::instance.units[unitID].uid;
                DAT_GameState::instance.playerDataArray[playerID]
                    .aiSiegeCreationInformation[siegeIndex][index]
                    .buildingID = 0;
                return;
            }
        }
    }

}
}

