    void AICState::aiRecruitEngineers(int playerID)
    {
        int const aiType = DAT_GameState::instance.playerDataArray[playerID].aiType;
        if (aiType == AITA_NULL)
            return;
        if (DAT_GameState::instance.playerDataArray[playerID].isEngineerRequired == FALSE)
