                                        DAT_GameSynchronyState::ptr)(_iPlayer),
                                    _isAI != FALSE))
                            && (DAT_GameState::instance.mapAndTime.playerTeams[_iPlayer]
                                == DAT_GameState::instance.mapAndTime.playerTeams[playerID])) {
                            /*
                              the other player is not in state 0 (recruiting units for attacking)
                             */
                            if (_pPlayerData->aiPlayerState != 0) {
                                return TRUE;
                            }
                            /*
                              This is the inverse check of the check on line 26:   totalAttackTroops -
                              DAT_PlayerDataArray[comparison   player].totalAttackingEngineerTroops <
                              DAT_AICArray[aiType of considered   player].AttForceBase + DAT_PlayerDataArray[considered
                              player].currentWaveRandomAttackingStrength
                             */
                            if (_pPlayerData->totalAttackTroops - _pPlayerData->totalAttackingEngineerTroops
                                < *(int*)((int)DAT_EntityState::instance.seagullArray + _pPlayerData->aiType * 0x2a4
                                      + 0x2664)
                                    + _pPlayerData->currentWaveRandomAttackingStrength) {
                                /*
                                  I do hope I have the comparison right, is this a strong or weak team member?
                                 */
                                _unreadyTeamMembers = _unreadyTeamMembers + 1;
                            } else {
