// FUNCTION: STRONGHOLDCRUSADER 0x004D30E0
 BOOLEnum AICState::sendUnitsToAttackBreachedCastle(int attackingPlayerIndex)
 {
 int vector = 0;
 if (DAT_GameState.playerDataArray[attackingPlayerIndex].aiType == AIT_NULL) {
 return TRUE;
 }
 BOOLEnum sentUnitsToAttackLord = FALSE;
 int const defendingLordID = getAliveLordForPlayer(DAT_GameState.playerDataArray[attackingPlayerIndex].attackedPlayerID);
 for (int i = 0; i < 11; i++) {
 int const tribeType = DAT_SkirmishDefinedData.MaxBreachTribes[i].tribeType;
 int const tribeCount = DAT_SkirmishDefinedData.MaxBreachTribes[i].tribeCount;
 if (tribeType == 18 || tribeType == 14 || tribeType == 13) {
 continue;
 }
 for (int j = 0; j < tribeCount; j++) {
 int const tribeID
 = DAT_GameState.playerDataArray[attackingPlayerIndex].aiTribeIDs[tribeType + j];
 if (tribeID == 0) {
 continue;
 }
 if (DAT_TribesState.tribes[tribeID].uid
 != DAT_GameState.playerDataArray[attackingPlayerIndex].aiTribeUIDs[j + tribeType]) {
 continue;
 }
 int const targetUnitID = (short)DAT_TribesState.tribes[tribeID].selectionTargetUnitID;
 DAT_TribesState.tribes[tribeID].unitStance = USE_DEFENSIVE;
 if (sentUnitsToAttackLord != FALSE || defendingLordID == 0 || tribeType == 186) {
 if (giveSomeRaidCommand(tribeID, tribeType)
