 continue;
 }
 if (tribeType == 186) {
 vector += 4;
 }
 DAT_TribesState.tribes[tribeID].tribeBehaviorType = STBT_8;
 DAT_TribesState.tribes[tribeID].unitStance
 = USE_AGGRESSIVE;
 int attackedPlayerID
 = DAT_GameState.playerDataArray[attackingPlayerIndex].attackedPlayerID;
 setAxisBasedDistanceResult(DAT_UnitsState.units[targetUnitID].x,
 DAT_UnitsState.units[targetUnitID].y,
 DAT_GameState.mapAndTime.attackVectors[attackedPlayerID][vector].x,
 DAT_GameState.mapAndTime.attackVectors[attackedPlayerID][vector].y);
 if (DAT_DirectionAlgorithmState.distanceHigh > 4) {
 attackedPlayerID
 = DAT_GameState.playerDataArray[attackingPlayerIndex].attackedPlayerID;
 giveTribeMoveInstruction(tribeID,
 DAT_GameState.mapAndTime.attackVectors[attackedPlayerID][vector].x,
 DAT_GameState.mapAndTime.attackVectors[attackedPlayerID][vector].y, 0, 0,
 UMSE_0);
 }
 vector += 1;
 } else {
 // Send units to attack lord
 int const lordY = DAT_UnitsState.units[defendingLordID].y;
 int const lordX = DAT_UnitsState.units[defendingLordID].x;
 if (giveTribeMoveInstruction(
 tribeID, lordX, lordY, 0, 0, UMSE_0)
 == 0) {
 return FALSE;
 }
 sentUnitsToAttackLord = TRUE;
 }
 }
 }
 return TRUE;
 }
}
