            if (_highestSize < *_pAreaSizes) {
                _largestAreaId = _scoreOffset + -1;
                _highestSize = *_pAreaSizes;
            }
            if (_highestSize < _pAreaSizes[1]) {
                _largestAreaId = _scoreOffset;
                _highestSize = _pAreaSizes[1];
