                char const notInLargestArea = this->heatMaps[gridX][gridY].tilesNotPartOfLargestAreaCount;
                if (notInLargestArea >= 16 || this->heatMaps[gridX][gridY].destructionBasedPlacementCooldown) {
                    continue;
