                            score *= 2;
                        }
                    }
                    if (score > bestScore) {
                        bestX = gridX;
                        bestY = gridY;
                        bestScore = score;
                    }
                    if (foundCount > 10 || (foundCount > 5 && this->visitCount > 20)
                        || (foundCount > 0 && this->visitCount > 30)) {
                        break;
                    }
                }
                this->heatMaps[gridX][gridY].algorithmVisitCountUnk = this->visitCount + 1;
